<template>
  <div class="wb" :data-theme="resolvedTheme">
    <section v-if="restoring" class="wb-card wb-auth-card" aria-live="polite">正在恢复登录状态…</section>
    <section v-else-if="!user" class="wb-card wb-auth-card">
      <template v-if="mode === 'login'">
        <p class="wb-kicker">LRC 工作站</p><h2>欢迎回来</h2><p class="wb-intro">登录后继续编辑和管理歌词项目。</p>
        <form novalidate @submit.prevent="login">
          <label class="wb-field" for="login-name">用户名<input id="login-name" v-model.trim="credentials.name" autocomplete="username" :aria-invalid="!!fieldErrors.name" :aria-describedby="fieldErrors.name ? 'login-name-error' : undefined" required></label><p v-if="fieldErrors.name" id="login-name-error" class="wb-field-error">{{ fieldErrors.name }}</p>
          <label class="wb-field" for="login-password">密码<span class="wb-password-input"><input id="login-password" v-model="credentials.password" :type="showLoginPassword ? 'text' : 'password'" autocomplete="current-password" :aria-invalid="!!fieldErrors.password" :aria-describedby="fieldErrors.password ? 'login-password-error' : undefined" required><button type="button" class="wb-password-toggle" :aria-label="showLoginPassword ? '隐藏密码' : '显示密码'" @click="showLoginPassword = !showLoginPassword">{{ showLoginPassword ? '隐藏' : '显示' }}</button></span></label><p v-if="fieldErrors.password" id="login-password-error" class="wb-field-error">{{ fieldErrors.password }}</p>
          <button class="wb-btn primary" :disabled="busy">{{ busy ? '正在登录…' : '登录' }}</button>
        </form>
        <button v-if="!setup.needsBootstrap" class="wb-link" :disabled="busy" @click="switchMode('register')">使用邀请码注册</button><button v-if="setup.needsBootstrap" class="wb-link" :disabled="busy" @click="switchMode('bootstrap')">设置首个管理员</button>
      </template>
      <template v-else-if="mode === 'register'">
        <p class="wb-kicker">LRC 工作站</p><h2>邀请码注册</h2><p class="wb-intro">邀请码请向管理员获取。创建后将直接进入工作台。</p>
        <form novalidate @submit.prevent="register">
          <label class="wb-field" for="invite-code">邀请码<input id="invite-code" v-model.trim="registerForm.invite_code" autocomplete="off" :aria-invalid="!!fieldErrors.invite_code" :aria-describedby="fieldErrors.invite_code ? 'invite-code-error' : undefined" required></label><p v-if="fieldErrors.invite_code" id="invite-code-error" class="wb-field-error">{{ fieldErrors.invite_code }}</p>
          <label class="wb-field" for="register-name">用户名<span class="wb-field-hint">3–32 位小写字母、数字、_ 或 -</span><input id="register-name" v-model.trim="registerForm.name" autocomplete="username" minlength="3" maxlength="32" pattern="[a-z0-9_-]{3,32}" :aria-invalid="!!fieldErrors.name" :aria-describedby="fieldErrors.name ? 'register-name-error' : undefined" required></label><p v-if="fieldErrors.name" id="register-name-error" class="wb-field-error">{{ fieldErrors.name }}</p>
          <label class="wb-field" for="register-display-name">展示名<span class="wb-field-hint">可选</span><input id="register-display-name" v-model.trim="registerForm.display_name" autocomplete="name"></label>
          <label class="wb-field" for="register-password">密码<span class="wb-field-hint">8–200 位</span><span class="wb-password-input"><input id="register-password" v-model="registerForm.password" :type="showRegisterPassword ? 'text' : 'password'" autocomplete="new-password" minlength="8" maxlength="200" :aria-invalid="!!fieldErrors.password" :aria-describedby="fieldErrors.password ? 'register-password-error' : undefined" required><button type="button" class="wb-password-toggle" :aria-label="showRegisterPassword ? '隐藏密码' : '显示密码'" @click="showRegisterPassword = !showRegisterPassword">{{ showRegisterPassword ? '隐藏' : '显示' }}</button></span></label><p v-if="fieldErrors.password" id="register-password-error" class="wb-field-error">{{ fieldErrors.password }}</p>
          <label class="wb-field" for="register-confirm-password">确认密码<input id="register-confirm-password" v-model="registerForm.confirmPassword" :type="showRegisterPassword ? 'text' : 'password'" autocomplete="new-password" :aria-invalid="!!fieldErrors.confirmPassword" :aria-describedby="fieldErrors.confirmPassword ? 'register-confirm-password-error' : undefined" required></label><p v-if="fieldErrors.confirmPassword" id="register-confirm-password-error" class="wb-field-error">{{ fieldErrors.confirmPassword }}</p>
          <button class="wb-btn primary" :disabled="busy">{{ busy ? '正在创建…' : '创建账户' }}</button>
        </form><button class="wb-link" :disabled="busy" @click="switchMode('login')">返回登录</button>
      </template>
      <template v-else>
        <p class="wb-kicker">LRC 工作站</p><h2>设置首个管理员</h2><p class="wb-intro">此入口仅在工作站尚未初始化时可用。</p>
        <form novalidate @submit.prevent="bootstrap"><label class="wb-field" for="bootstrap-token">部署引导口令<input id="bootstrap-token" v-model="bootstrapForm.token" type="password" autocomplete="off" :aria-invalid="!!fieldErrors.token" :aria-describedby="fieldErrors.token ? 'bootstrap-token-error' : undefined" required></label><p v-if="fieldErrors.token" id="bootstrap-token-error" class="wb-field-error">{{ fieldErrors.token }}</p><label class="wb-field" for="bootstrap-name">用户名<span class="wb-field-hint">3–32 位小写字母、数字、_ 或 -</span><input id="bootstrap-name" v-model.trim="bootstrapForm.name" autocomplete="username" :aria-invalid="!!fieldErrors.name" :aria-describedby="fieldErrors.name ? 'bootstrap-name-error' : undefined" required></label><p v-if="fieldErrors.name" id="bootstrap-name-error" class="wb-field-error">{{ fieldErrors.name }}</p><label class="wb-field" for="bootstrap-display-name">展示名<span class="wb-field-hint">可选</span><input id="bootstrap-display-name" v-model.trim="bootstrapForm.display_name" autocomplete="name"></label><label class="wb-field" for="bootstrap-password">密码<span class="wb-field-hint">8–200 位</span><input id="bootstrap-password" v-model="bootstrapForm.password" type="password" autocomplete="new-password" :aria-invalid="!!fieldErrors.password" :aria-describedby="fieldErrors.password ? 'bootstrap-password-error' : undefined" required></label><p v-if="fieldErrors.password" id="bootstrap-password-error" class="wb-field-error">{{ fieldErrors.password }}</p><button class="wb-btn primary" :disabled="busy">{{ busy ? '正在创建…' : '创建管理员' }}</button></form><button class="wb-link" :disabled="busy" @click="switchMode('login')">返回登录</button>
      </template>
      <p v-if="message" class="wb-msg" :class="{ err: failed }" :role="failed ? 'alert' : 'status'">{{ message }}</p>
    </section>
    <template v-else><p v-if="message" class="wb-msg" :class="{ err: failed }" :role="failed ? 'alert' : 'status'">{{ message }}</p><Workspace ref="workspace" :user="user" :theme="resolvedTheme" @unauthorized="endSession" @account="openVirtual('account')" @users="openVirtual('users')"><template #account><AccountSettingsView :user="user" :github-configured="setup.githubConfigured" :adapter="auth" @user="updateUser" @unauthorized="endSession" /></template><template #users><WorkspaceUsersView v-if="user.role === 'admin'" :adapter="auth" @unauthorized="endSession" /></template></Workspace><footer class="wb-footer"><span>{{ user.display_name || user.name }} · {{ user.role === 'admin' ? '管理员' : '编辑者' }}</span><label for="wb-theme">主题</label><select id="wb-theme" v-model="themePreference" class="wb-theme-select" aria-label="工作站主题"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">暗色</option></select><button class="wb-btn" type="button" @click="logout">退出</button></footer></template>
  </div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import Workspace from './Workspace.vue'; import AccountSettingsView from './AccountSettingsView.vue'; import WorkspaceUsersView from './WorkspaceUsersView.vue'; import { createAuthAdapter } from './authAdapter.js';
const THEME_KEY = 'lrc-workstation-theme'; const auth = createAuthAdapter(); const workspace = ref(null); const user = ref(null); const setup = ref({ needsBootstrap: false, githubConfigured: false }); const restoring = ref(true); const busy = ref(false); const mode = ref('login'); const message = ref(''); const failed = ref(false); const fieldErrors = ref({}); const themePreference = ref('system'); const systemDark = ref(false); const showLoginPassword = ref(false); const showRegisterPassword = ref(false);
const credentials = ref({ name: '', password: '' }); const registerForm = ref({ invite_code: '', name: '', display_name: '', password: '', confirmPassword: '' }); const bootstrapForm = ref({ token: '', name: '', display_name: '', password: '' }); const resolvedTheme = computed(() => themePreference.value === 'system' ? (systemDark.value ? 'dark' : 'light') : themePreference.value);
function report(value = '', isFailed = false) { message.value = value; failed.value = isFailed; } function updateUser(next) { user.value = next; }
function clearFormState() { report(); fieldErrors.value = {}; credentials.value.password = ''; registerForm.value.password = ''; registerForm.value.confirmPassword = ''; bootstrapForm.value.token = ''; bootstrapForm.value.password = ''; showLoginPassword.value = false; showRegisterPassword.value = false; }
function switchMode(next) { if (busy.value) return; clearFormState(); mode.value = next; }
function validateLogin() { const errors = {}; if (!credentials.value.name) errors.name = '请输入用户名。'; if (!credentials.value.password) errors.password = '请输入密码。'; fieldErrors.value = errors; return !Object.keys(errors).length; }
function validateRegister() { const errors = {}; if (!registerForm.value.invite_code) errors.invite_code = '请输入邀请码。'; if (!/^[a-z0-9_-]{3,32}$/.test(registerForm.value.name)) errors.name = '用户名需为 3–32 位小写字母、数字、_ 或 -。'; if (registerForm.value.password.length < 8 || registerForm.value.password.length > 200) errors.password = '密码需为 8–200 位。'; if (registerForm.value.password !== registerForm.value.confirmPassword) errors.confirmPassword = '两次输入的密码不一致。'; fieldErrors.value = errors; return !Object.keys(errors).length; }
function validateBootstrap() { const errors = {}; if (!bootstrapForm.value.token) errors.token = '请输入部署引导口令。'; if (!/^[a-z0-9_-]{3,32}$/.test(bootstrapForm.value.name)) errors.name = '用户名需为 3–32 位小写字母、数字、_ 或 -。'; if (bootstrapForm.value.password.length < 8 || bootstrapForm.value.password.length > 200) errors.password = '密码需为 8–200 位。'; fieldErrors.value = errors; return !Object.keys(errors).length; }
async function call(action) { busy.value = true; report(); try { const data = await action(); if (data?.user) user.value = data.user; return data; } catch (error) { report(error.message || '网络错误，请重试', true); return null; } finally { busy.value = false; } }
async function login() { if (busy.value) return; report(); if (!validateLogin()) return; const data = await call(() => auth.login(credentials.value.name, credentials.value.password)); if (data?.user) credentials.value.password = ''; }
async function register() { if (busy.value) return; report(); if (!validateRegister()) return; const data = await call(() => auth.register(registerForm.value.invite_code, registerForm.value.name, registerForm.value.password, registerForm.value.display_name)); if (data?.user) { registerForm.value.password = ''; registerForm.value.confirmPassword = ''; } }
async function bootstrap() { if (busy.value) return; report(); if (!validateBootstrap()) return; const data = await call(() => auth.bootstrap(bootstrapForm.value.token, bootstrapForm.value.name, bootstrapForm.value.password, bootstrapForm.value.display_name)); if (data?.user) { setup.value.needsBootstrap = false; bootstrapForm.value = { token: '', name: '', display_name: '', password: '' }; } }
function endSession() { user.value = null; switchMode(setup.value.needsBootstrap ? 'bootstrap' : 'login'); report('登录已失效，请重新登录', true); } async function logout() { if (!workspace.value?.canLeave?.()) return; try { await auth.logout(); } catch (error) { report(error.message || '退出失败，请重试', true); return; } user.value = null; switchMode(setup.value.needsBootstrap ? 'bootstrap' : 'login'); } async function openVirtual(view) { if (view === 'users' && user.value?.role !== 'admin') return; await nextTick(); workspace.value?.openVirtualView?.(view); }
function handleGithubResult() { const params = new URLSearchParams(window.location.search); if (!params.has('github')) return; const connected = params.get('github') === 'connected'; report(connected ? 'GitHub 已绑定' : `GitHub 绑定失败：${params.get('reason') || '未知错误'}`, !connected); params.delete('github'); params.delete('reason'); window.history.replaceState({}, '', window.location.pathname + (params.size ? '?' + params.toString() : '') + window.location.hash); if (connected) auth.me().then((data) => { if (data.user) user.value = data.user; }).catch(endSession); }
let media; const onThemeChange = (event) => { systemDark.value = event.matches; }; onMounted(async () => { try { const stored = localStorage.getItem(THEME_KEY); themePreference.value = ['system', 'light', 'dark'].includes(stored) ? stored : 'system'; } catch {} media = window.matchMedia('(prefers-color-scheme: dark)'); systemDark.value = media.matches; media.addEventListener('change', onThemeChange); try { setup.value = await auth.setup(); const data = await auth.me(); user.value = data.user; handleGithubResult(); } catch (error) { if (error.status !== 401) report(error.message || '无法连接认证服务', true); mode.value = setup.value.needsBootstrap ? 'bootstrap' : 'login'; } finally { restoring.value = false; } }); onBeforeUnmount(() => media?.removeEventListener('change', onThemeChange)); watch(themePreference, (value) => { try { localStorage.setItem(THEME_KEY, value); } catch {} });
</script>

<style scoped>
.wb { margin:1.5rem auto; --bg-color:#f7f7f8; --surface:#fff; --text-color:#202124; --muted:#6b6f76; --border-color:#d9dade; color:var(--text-color); }.wb[data-theme='dark'] { --bg-color:#171719; --surface:#202022; --text-color:#f1f1f2; --muted:#aaadb3; --border-color:#3a3b40; color-scheme:dark; }.wb-auth-card { width:min(100%,27.5rem); box-sizing:border-box; margin:clamp(2rem,8vh,5rem) auto; padding:clamp(1.5rem,5vw,2.25rem); border:1px solid var(--border-color); border-radius:8px; background:var(--surface); box-shadow:0 12px 32px rgba(0,0,0,.06); }.wb-card h2 { margin:.1rem 0 0; font-size:1.45rem; letter-spacing:-.02em; }.wb-kicker { margin:0; color:var(--muted); font-size:.78rem; font-weight:650; letter-spacing:.08em; }.wb-intro { margin:.35rem 0 1.45rem; color:var(--muted); font-size:.9rem; line-height:1.55; }.wb-card form { display:grid; gap:1rem; }.wb-field { display:grid; gap:.42rem; font-size:.88rem; font-weight:600; }.wb-field-hint { color:var(--muted); font-size:.77rem; font-weight:400; }.wb-theme-select,.wb-btn,.wb-card input { box-sizing:border-box; width:100%; min-height:2.65rem; padding:.58rem .72rem; border:1px solid var(--border-color); border-radius:5px; color:inherit; background:var(--surface); font:inherit; }.wb-card input:focus { outline:2px solid #737780; outline-offset:1px; border-color:#737780; }.wb-card input[aria-invalid='true'] { border-color:#c53b3b; }.wb-password-input { display:flex; align-items:center; position:relative; }.wb-password-input input { padding-right:4.2rem; }.wb-password-toggle { position:absolute; right:.25rem; padding:.3rem .45rem; border:0; color:var(--muted); background:transparent; font:inherit; font-size:.78rem; cursor:pointer; }.wb-field-error { margin:-.65rem 0 0; color:#b42318; font-size:.8rem; line-height:1.35; }.wb-btn,.wb-link { cursor:pointer; }.wb-btn.primary { color:#fff; background:#303136; border-color:#303136; font-weight:650; }.wb[data-theme='dark'] .wb-btn.primary { color:#171719; background:#f2f2f3; border-color:#f2f2f3; }.wb-link { justify-self:start; margin-top:1rem; padding:0; border:0; color:var(--muted); background:transparent; font:inherit; font-size:.85rem; text-decoration:underline; text-underline-offset:3px; }.wb-btn:disabled,.wb-link:disabled { opacity:.5; cursor:not-allowed; }.wb-msg { margin:1rem 0 0; color:var(--muted); font-size:.85rem; line-height:1.45; }.wb-msg.err { color:#b42318; }.wb[data-theme='dark'] .wb-msg.err,.wb[data-theme='dark'] .wb-field-error { color:#ff9898; }.wb-footer { background:var(--surface); padding:.55rem .75rem; display:flex; align-items:center; justify-content:flex-end; gap:.5rem; margin-top:.55rem; border-top:1px solid var(--border-color); font-size:.82rem; }.wb-footer .wb-btn,.wb-footer .wb-theme-select { width:auto; min-height:auto; }.wb-footer .wb-btn { padding:.45rem .65rem; } @media (max-width:480px) { .wb { margin:0; }.wb-auth-card { width:100%; min-height:100vh; margin:0; border:0; border-radius:0; box-shadow:none; }.wb-footer { flex-wrap:wrap; justify-content:flex-start; } }
</style>
